create table public.los_studio_recovery (user_id uuid not null references auth.users(id) on delete cascade, revision bigint not null, state jsonb not null check (jsonb_typeof(state)='object'), created_at timestamptz not null default now(), primary key(user_id,revision)); alter table public.los_studio_recovery enable row level security; revoke all on public.los_studio_recovery from anon,authenticated; grant select,insert on public.los_studio_recovery to authenticated; create policy los_recovery_read on public.los_studio_recovery for select to authenticated using ((select auth.uid())=user_id); create policy los_recovery_insert on public.los_studio_recovery for insert to authenticated with check ((select auth.uid())=user_id);
